"""Real temporary Git/filesystem lifecycle, synthetic nonsecret generated bytes."""
import ast,copy,json,os,stat,subprocess,tempfile,unittest
from pathlib import Path
from unittest import mock
import refresh_truth_receipt as C
from test_refresh_truth_receipt import fixture
OWNER='SideStore/Dependencies/minimuxer'
class GeneratedLifecycleTests(unittest.TestCase):
 def setUp(self):
  self.tmp=tempfile.TemporaryDirectory();self.sources=Path(self.tmp.name).resolve()/'sources';self.root=self.sources/OWNER;self.root.mkdir(parents=True)
  self.git=lambda *args:subprocess.check_output(['git','-C',str(self.root),*args],text=True).strip()
  self.git('init','-q');self.git('config','user.name','fixture');self.git('config','user.email','fixture@example.invalid')
  (self.root/'source.swift').write_text('let unchanged = 1\n');self.git('add','.');self.git('commit','-qm','owned fixture')
  self.commit=self.git('rev-parse','HEAD');self.tree=self.git('rev-parse','HEAD^{tree}')
  self.graph={'owners':{OWNER:['NRG-Wardog/minimuxer',self.commit]},'reviewed_deltas':{OWNER:{'tree':self.tree}}}
  self.patch=mock.patch.object(C,'INPUTS',{OWNER:('source.swift',)});self.patch.start();self.before=C.collect(self.sources,self.graph)
  self.base=self.root/'GeneratedDependencies/RemotePairingKit';self.base.mkdir(parents=True)
  (self.base/'.gitignore').write_text('ignored.bin\n');(self.base/'Package.swift').write_text('// inert fixture\n');(self.base/'ignored.bin').write_bytes(b'nonsecret synthetic generated library')
  (self.base/'empty').mkdir()
  self.evidence=Path(self.tmp.name)/'evidence';self.evidence.mkdir()
  rows={}
  for p in [self.base,*sorted(self.base.rglob('*'))]:
   row={'kind':'directory' if p.is_dir() else 'file','mode':stat.S_IMODE(p.stat().st_mode)}
   if p.is_file():row['sha256']=C.sha(p)
   rows[p.relative_to(self.base).as_posix()]=row
  self.generated={'present':True,'relative_path':OWNER+'/GeneratedDependencies/RemotePairingKit','files':rows}
  v=fixture();self.identity=v['identity'];stage={'schema':'same-run-generated-embedded-openssl-input-v1',**self.identity,'consumer_commit':self.commit,'generated':self.generated}
  stage_path=self.evidence/'generated-embedded-openssl-stage.json';stage_path.write_text(json.dumps(stage))
  self.inventory={OWNER:{'commit':self.commit,'tree':self.tree,'files':{'source.swift':{'mode':'100644','sha256':C.sha(self.root/'source.swift')}}},'local-framework':{},'generated-embedded-openssl':{**self.generated,'stage_receipt_sha256':C.sha(stage_path)}}
  for name in ('compiler-inputs.json','after-build.json'):(self.evidence/name).write_text(json.dumps(self.inventory))
  v['source_graph']=self.graph['owners']
  for part in v['parts'].values():part['source_graph']=self.graph['owners'];part['source']=self.before
  v['part_sha256']={k:C.digest(p) for k,p in v['parts'].items()}
  self.receipt=self.evidence/'refresh-truth-tests.json';self.receipt.write_text(json.dumps(v))
 def tearDown(self):self.patch.stop();self.tmp.cleanup()
 def verify(self):return C.verify_local(self.receipt,self.sources,self.graph,self.identity,compiler_evidence=self.evidence)
 def actual_call_sites(self):
  folder=Path(__file__).resolve().parent;result=[]
  for filename,count in (('record.py',1),('package_candidate.py',2)):
   tree=ast.parse((folder/filename).read_text())
   calls=[n for n in ast.walk(tree) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='verify_refresh_truth']
   self.assertEqual(len(calls),count)
   for call in sorted(calls,key=lambda n:n.lineno):
    self.assertEqual([k.arg for k in call.keywords],['compiler_evidence'])
    result.append((filename+':'+str(call.lineno),compile(ast.Expression(call),filename,'eval')))
  return result
 def invoke_actual_call(self,expression):
  context={'verify_refresh_truth':C.verify_local,'Path':Path,'S':self.sources,'E':self.evidence,'load_candidate_graph':lambda:self.graph,'os':os,'refresh_truth_receipt':self.receipt,'native_identity':self.identity}
  env={key:self.identity[field] for field,key in [('workflow_commit','GITHUB_SHA'),('run_id','GITHUB_RUN_ID'),('run_attempt','GITHUB_RUN_ATTEMPT')]}
  old=Path.cwd()
  try:
   os.chdir(self.sources.parent)
   with mock.patch.dict(os.environ,env):return eval(expression,context)
  finally:os.chdir(old)
 def test_actual_record_and_pre_post_package_calls_propagate_sealed_inventory(self):
  self.assertIn('GeneratedDependencies/RemotePairingKit/Package.swift',self.git('ls-files','--others','--exclude-standard'))
  for name,expression in self.actual_call_sites():
   with self.subTest(call=name):self.invoke_actual_call(expression)
  self.assertEqual(C.collect(self.sources,self.graph,self.inventory),self.before)
  (self.root/'unsealed.swift').write_text('unexpected fixture')
  for name,expression in self.actual_call_sites():
   with self.subTest(call=name),self.assertRaisesRegex(ValueError,'unsealed generated source file'):self.invoke_actual_call(expression)
 def test_ignored_bytes_missing_entry_extra_entry_and_mode_rejected(self):
  p=self.base/'ignored.bin';original=p.read_bytes();p.write_bytes(b'changed')
  with self.assertRaisesRegex(ValueError,'inventory differs'):self.verify()
  p.write_bytes(original);p.unlink()
  with self.assertRaisesRegex(ValueError,'inventory differs'):self.verify()
  p.write_bytes(original);extra=self.base/'unsealed';extra.write_text('extra')
  with self.assertRaisesRegex(ValueError,'inventory differs'):self.verify()
  extra.unlink();p.chmod(0o755)
  with self.assertRaisesRegex(ValueError,'inventory differs'):self.verify()
 def test_symlink_and_empty_directory_mode_rejected(self):
  p=self.base/'Package.swift';p.unlink();p.symlink_to(self.root/'source.swift')
  with self.assertRaisesRegex(ValueError,'linked/nonregular'):self.verify()
  p.unlink();p.write_text('// inert fixture\n');(self.base/'empty').chmod(0o700)
  with self.assertRaisesRegex(ValueError,'inventory differs'):self.verify()
 def test_foreign_path_and_rehashed_foreign_run_rejected(self):
  x=copy.deepcopy(self.inventory);x['generated-embedded-openssl']['relative_path']='wrong/owner'
  with self.assertRaisesRegex(ValueError,'owner path'):C.collect(self.sources,self.graph,x)
  p=self.evidence/'generated-embedded-openssl-stage.json';s=json.loads(p.read_text());s['run_id']='999';p.write_text(json.dumps(s));x=copy.deepcopy(self.inventory);x['generated-embedded-openssl']['stage_receipt_sha256']=C.sha(p)
  for n in ('compiler-inputs.json','after-build.json'):(self.evidence/n).write_text(json.dumps(x))
  with self.assertRaisesRegex(ValueError,'stage run differs'):self.verify()
 def test_generated_stage_hash_and_upstream_pin_remain_bound(self):
  stage_path=self.evidence/'generated-embedded-openssl-stage.json'
  stage=json.loads(stage_path.read_text());stage['consumer_commit']='f'*40;stage_path.write_text(json.dumps(stage))
  with self.assertRaisesRegex(ValueError,'receipt hash differs'):self.verify()
  stage['consumer_commit']=self.commit
  graph=copy.deepcopy(self.graph);graph['owners']['RemotePairingKit']=['mahee96/RemotePairingKit','a'*40]
  stage['generated']['source_commit']='a'*40;stage['generated']['source_tree']='b'*40
  stage_path.write_text(json.dumps(stage));inventory=copy.deepcopy(self.inventory)
  inventory['generated-embedded-openssl']={**stage['generated'],'stage_receipt_sha256':C.sha(stage_path)}
  inventory['RemotePairingKit']={'commit':'a'*40,'tree':'b'*40}
  def save():
   for name in ('compiler-inputs.json','after-build.json'):(self.evidence/name).write_text(json.dumps(inventory))
  save();C.sealed_compiler_inventory(self.evidence,graph,self.identity)
  inventory['RemotePairingKit']['commit']='c'*40;save()
  with self.assertRaisesRegex(ValueError,'upstream pin differs'):C.sealed_compiler_inventory(self.evidence,graph,self.identity)
 def test_unsealed_outside_stage_and_tracked_changes_remain_rejected(self):
  p=self.root/'unexpected.swift';p.write_text('extra')
  with self.assertRaisesRegex(ValueError,'unsealed generated source file'):self.verify()
  p.unlink();(self.root/'source.swift').write_text('changed')
  with self.assertRaisesRegex(ValueError,'tracked compiler source'):self.verify()
if __name__=='__main__':unittest.main(verbosity=2)
